const RUNES = {"8112":{"name":"Électrocution","icon":"perk-images/Styles/Domination/Electrocute/Electrocute.png","style":8100,"slot":0,"shortDesc":"Toucher un champion avec 3 attaques ou compétences <b>différentes</b> en moins de 3 sec inflige des <lol-uikit-tooltipped-keyword key='LinkTooltip_Description_AdaptiveDmg'>dégâts adaptatifs</lol-uikit-tooltipped-keyword> supplémentaires.","longDesc":"Toucher un champion ennemi avec 3 attaques ou compétences <b>différentes</b> en moins de 3 sec inflige des <lol-uikit-tooltipped-keyword key='LinkTooltip_Description_AdaptiveDmg'><font color='#48C4B7'>dégâts adaptatifs</font></lol-uikit-tooltipped-keyword> bonus.<br><br>Dégâts : 70 - 240 (+0.1 dégâts d'attaque bonus, +0.05 puissance) pts de dégâts.<br>Délai de récupération : 20 sec.<br><br><i>« On les appelait les seigneurs de la foudre, car parler de leurs éclairs était une invitation à l'anéantissement. »</i>"},"8128":{"name":"Moisson noire","icon":"perk-images/Styles/Domination/DarkHarvest/DarkHarvest.png","style":8100,"slot":0,"shortDesc":"Blesser un champion à qui il reste peu de PV lui inflige des <lol-uikit-tooltipped-keyword key='LinkTooltip_Description_AdaptiveDmg'>dégâts adaptatifs</lol-uikit-tooltipped-keyword> et siphonne son âme.","longDesc":"Blesser un champion qui a moins de 50% de ses PV lui inflige des <lol-uikit-tooltipped-keyword key='LinkTooltip_Description_AdaptiveDmg'>dégâts adaptatifs</lol-uikit-tooltipped-keyword> et siphonne son âme, ce qui augmente définitivement les dégâts de Moisson noire de 11.<br><br>Dégâts de Moisson noire : 30 (+11 pts de dégâts par âme) (+0.1 dégâts d'attaque bonus) (+0.05 puissance).<br>Délai de récupération : 35 sec (réinitialisé à 1.0 sec à chaque élimination)."},"9923":{"name":"Déluge de lames","icon":"perk-images/Styles/Domination/HailOfBlades/HailOfBlades.png","style":8100,"slot":0,"shortDesc":"Pour vos 3 premières attaques contre des champions ennemis, votre vitesse d'attaque augmente grandement et vous gagnez des <trueDamage>dégâts bruts bonus</trueDamage>.","longDesc":"Quand vous attaquez un champion ennemi, votre vitesse d'attaque et vos <trueDamage>dégâts bruts bonus</trueDamage> augmentent de 90% (60% pour les champions à distance) pour 3 attaques.<br><br>Cet effet prend fin s'il s'écoule plus de 3 sec entre deux attaques.<br><br>Délai de récupération : 10 sec.<br>Dégâts à l'impact : 2 - 20 (+0.12 dégâts d'attaque bonus, +0.1 puissance) pts de dégâts.<br><br><rules>Les réinitialisations d'attaque augmentent le nombre d'attaques max de 1.<br>Permet de dépasser temporairement la limite de vitesse d'attaque.</rules>"},"8126":{"name":"Coup bas","icon":"perk-images/Styles/Domination/CheapShot/CheapShot.png","style":8100,"slot":1,"shortDesc":"Vous infligez des dégâts bruts supplémentaires aux champions ennemis dont <lol-uikit-tooltipped-keyword key='LinkTooltip_Description_ImpairAct'>les actions ou les déplacements sont restreints.</lol-uikit-tooltipped-keyword> ","longDesc":"Blesser des champions dont <b>les actions ou les déplacements sont restreints</b> leur inflige 10 - 45 pts de dégâts bruts supplémentaires (selon le niveau).<br><br>Délai de récupération : 4 sec.<br><rules>S'active avec les dégâts qui surviennent après la restriction.</rules>"},"8139":{"name":"Goût du sang","icon":"perk-images/Styles/Domination/TasteOfBlood/GreenTerror_TasteOfBlood.png","style":8100,"slot":1,"shortDesc":"Vous récupérez des PV quand vous blessez un champion ennemi.","longDesc":"Vous récupérez des PV quand vous blessez un champion ennemi.<br><br>Soins : 16 - 40 (+0.1 dégâts d'attaque supplémentaires, +0.05 puissance) PV (selon le niveau).<br><br>Délai de récupération : 20 sec."},"8143":{"name":"Ruée offensive","icon":"perk-images/Styles/Domination/SuddenImpact/SuddenImpact.png","style":8100,"slot":1,"shortDesc":"Après avoir utilisé une ruée, un bond, un saut instantané ou une téléportation ou en cessant d'être furtif, vous infligez des dégâts bruts bonus aux champions ennemis avec vos attaques de base et vos compétences qui infligent des dégâts.","longDesc":"Pendant 4 sec après avoir utilisé une ruée, un bond, un saut instantané ou une téléportation ou en cessant d'être furtif, vous infligez <trueDamage>20-80 pts de dégâts bruts</trueDamage> bonus (selon votre niveau) aux champions ennemis avec vos attaques de base et vos compétences qui infligent des dégâts.<br><br>Délai de récupération : 10 sec."},"8137":{"name":"Sixième sens","icon":"perk-images/Styles/Domination/SixthSense/SixthSense.png","style":8100,"slot":2,"shortDesc":"Long délai de récupération. Repère automatiquement une balise proche qui n'a pas été vue ni suivie, et la suit pour l'équipe. <br><br>Niveau 11 : révèle également la balise pendant 10 sec.","longDesc":"Repère automatiquement une balise proche qui n'a pas été vue ni suivie, et la suit pour l'équipe. <br><br>Niveau 11 : Révèle également la balise pendant 10 sec.<br><br>Cet effet a un délai de récupération de 250 sec."},"8140":{"name":"Souvenirs épouvantables","icon":"perk-images/Styles/Domination/GrislyMementos/GrislyMementos.png","style":8100,"slot":2,"shortDesc":"Vous gagnez 1 souvenir quand vous participez à l'<lol-uikit-tooltipped-keyword key='LinkTooltip_Description_Takedown'>élimination</lol-uikit-tooltipped-keyword> d'un champion (max 18).<br><br>Vous gagnez +6 accélération de compétence de relique par souvenir récupéré.","longDesc":"Vous gagnez 1 souvenir quand vous participez à l'<lol-uikit-tooltipped-keyword key='LinkTooltip_Description_Takedown'>élimination</lol-uikit-tooltipped-keyword> d'un champion (max 18).<br><br>Vous gagnez +6 accélération de compétence de relique par souvenir récupéré. Dans les modes de jeu où les reliques de vision n'existent pas, vous gagnez à la place +3 accélération de sort d'invocateur par souvenir."},"8141":{"name":"Balise de profondeur","icon":"perk-images/Styles/Domination/DeepWard/DeepWard.png","style":8100,"slot":2,"shortDesc":"Vos balises dans la jungle ennemie sont <keywordMajor>en profondeur</keywordMajor>, ce qui augmente leurs PV et leur durée.<br><br>Niveau 9 : les balises posées dans la rivière sont également <keywordMajor>en profondeur</keywordMajor>.","longDesc":"Vos balises dans la jungle ennemie sont <keywordMajor>en profondeur</keywordMajor>. Les balises <keywordMajor>en profondeur</keywordMajor> gagnent +1 PV bonus et durent [30 - 45] sec de plus (les Balises camouflées provenant de reliques durent [45 - 150] sec de plus à la place).<br><br>Niveau 9 : les balises posées dans la rivière sont également <keywordMajor>en profondeur</keywordMajor>."},"8135":{"name":"Chasseur de trésors","icon":"perk-images/Styles/Domination/TreasureHunter/TreasureHunter.png","style":8100,"slot":3,"shortDesc":"Participer à <lol-uikit-tooltipped-keyword key='LinkTooltip_Description_Takedown'>l'élimination</lol-uikit-tooltipped-keyword> d'un champion <b>unique</b> vous octroie des PO supplémentaires (une fois par champion). ","longDesc":"Vous gagnerez <gold>50 PO</gold> supplémentaires la prochaine fois que vous cumulerez un effet <i>Chasseur de primes</i>. Vous gagnez <gold>20 PO</gold> supplémentaires à chaque effet <i>Chasseur de primes</i> cumulé, jusqu'à <gold>130 PO</gold>.<br><br>Vous gagnez un effet <i>Chasseur de primes</i> la première fois que vous participez à l'élimination de chaque champion ennemi."},"8105":{"name":"Chasseur acharné","icon":"perk-images/Styles/Domination/RelentlessHunter/RelentlessHunter.png","style":8100,"slot":3,"shortDesc":"Participer à l'<lol-uikit-tooltipped-keyword key='LinkTooltip_Description_Takedown'>élimination</lol-uikit-tooltipped-keyword> d'un champion <b>unique</b> augmente définitivement votre <b><lol-uikit-tooltipped-keyword key='LinkTooltip_Description_MS'>vitesse de déplacement</lol-uikit-tooltipped-keyword> en dehors des combats</b>. ","longDesc":"Vous gagnez <speed>+8 vitesse de déplacement</speed> en dehors des combats par effet <i>Chasseur de primes</i> cumulé. Vous gagnez un effet <i>Chasseur de primes</i> la première fois que vous participez à l'élimination de chaque champion ennemi."},"8106":{"name":"Chasseur ultime","icon":"perk-images/Styles/Domination/UltimateHunter/UltimateHunter.png","style":8100,"slot":3,"shortDesc":"Participer à <lol-uikit-tooltipped-keyword key='LinkTooltip_Description_Takedown'>l'élimination</lol-uikit-tooltipped-keyword> d'un champion <b>unique</b> réduit définitivement le délai de récupération de votre ultime. ","longDesc":"Votre ultime gagne <attention>+6</attention> accélération de compétence et <attention>+5</attention> accélération de compétence par effet <i>Chasseur de primes</i> cumulé. Vous gagnez un effet <i>Chasseur de primes</i> la première fois que vous participez à l'élimination de chaque champion ennemi."},"8351":{"name":"Optimisation glaciale","icon":"perk-images/Styles/Inspiration/GlacialAugment/GlacialAugment.png","style":8300,"slot":0,"shortDesc":"Immobiliser un champion ennemi fait jaillir 3 rayons glaciaux qui ralentissent les ennemis proches et qui réduisent leurs dégâts contre vos alliés.","longDesc":"Quand vous immobilisez un champion ennemi, 3 rayons glaciaux jaillissent de lui dans votre direction et celle des autres champions proches. Cela crée pendant 3 sec (+ la durée de l'immobilisation) des zones gelées qui ralentissent les ennemis de 20% (+90% tous les 100% d'efficacité de vos soins et boucliers) (+6% tous les 100 pts de puissance) (+7% tous 100 pts de dégâts d'attaque bonus) et qui réduisent leurs dégâts de 15% contre vos alliés (mais pas contre vous). <br><br>Délai de récupération : 25 sec."},"8360":{"name":"Grimoire déchaîné","icon":"perk-images/Styles/Inspiration/UnsealedSpellbook/UnsealedSpellbook.png","style":8300,"slot":0,"shortDesc":"Changez vos sorts d'invocateur en dehors des combats. Les échanger contre des sorts d'invocateur uniques augmente la fréquence à laquelle vous pouvez faire des échanges.","longDesc":"Échangez l'un de vos sorts d'invocateur contre un autre sort d'invocateur à usage unique. Chaque sort d'invocateur échangé réduit définitivement de 25 sec le délai de récupération des échanges (délai initial : @f3@ sec). <br><br>Le premier échange est possible au bout de 6 minutes de jeu. <br><rules><br>Les sorts d'invocateur ne peuvent être échangés qu'en dehors des combats. <br>Après avoir utilisé un sort d'invocateur échangé, vous devez procéder à 3 autres échanges avant de pouvoir à nouveau sélectionner le premier.<br>Les dégâts de Châtiment augmentent après deux échanges de sorts d'invocateur. </rules>"},"8369":{"name":"Premier coup","icon":"perk-images/Styles/Inspiration/FirstStrike/FirstStrike.png","style":8300,"slot":0,"shortDesc":"Quand vous commencez un combat contre un champion, vous infligez 7% de dégâts supplémentaires pendant 3 sec et gagnez des PO selon les dégâts que vous infligez.","longDesc":"Vos attaques ou compétences contre un champion ennemi dans les 0.25 sec après le début du combat vous octroient 10 PO et <b>Premier coup</b> pendant 3 sec, ce qui vous permet d'infliger <truedamage>7%</truedamage> de <truedamage>dégâts</truedamage> supplémentaires aux champions et de gagner des <gold>PO</gold> équivalentes à <gold>50% (35% pour les champions à distance)</gold> des dégâts supplémentaires infligés.<br><br>Délai de récupération : <scaleLevel>25-15</scaleLevel> sec."},"8306":{"name":"Canaliportation Hextech","icon":"perk-images/Styles/Inspiration/HextechFlashtraption/HextechFlashtraption.png","style":8300,"slot":1,"shortDesc":"Quand Saut éclair est en récupération, il est remplacé par <i>Saut Hextech</i>.<br><br><i>Saut Hextech</i> : après une canalisation, vous vous téléportez à un autre endroit.","longDesc":"Quand votre Saut éclair est en récupération, il est remplacé par <i>Saut Hextech</i>.<br><br><i>Saut Hextech</i> : après 2 sec de canalisation, vous vous téléportez à un autre endroit.<br><br>Délai de récupération : 20 sec. A un délai de récupération de 10 sec quand vous entrez en combat avec un champion."},"8304":{"name":"Chaussures magiques","icon":"perk-images/Styles/Inspiration/MagicalFootwear/MagicalFootwear.png","style":8300,"slot":1,"shortDesc":"Vous obtenez des bottes gratuites après 12 min de jeu, mais vous ne pouvez pas acheter de bottes avant cela. Chaque fois que vous participez à <lol-uikit-tooltipped-keyword key='LinkTooltip_Description_Takedown'>l'élimination</lol-uikit-tooltipped-keyword> d'un champion, vous recevez vos bottes 45 sec plus tôt.","longDesc":"Vous obtenez des Chaussures légèrement magiques après 12 minutes de jeu, mais vous ne pouvez pas acheter de bottes avant cela. Chaque fois que vous participez à l'élimination d'un champion, vous obtenez les bottes 45 sec plus tôt.<br><br>Les Chaussures légèrement magiques vous octroient <speed>+10 vitesse de déplacement</speed>."},"8321":{"name":"Remise immédiate","icon":"perk-images/Styles/Inspiration/CashBack/CashBack2.png","style":8300,"slot":1,"shortDesc":"Vous récupérez des PO quand vous achetez des objets légendaires.","longDesc":"Vous récupérez 7.5% des PO dépensées quand vous achetez des objets légendaires."},"8313":{"name":"Triple tonique","icon":"perk-images/Styles/Inspiration/PerfectTiming/AlchemistCabinet.png","style":8300,"slot":2,"shortDesc":"Quand vous atteignez le niveau 3, vous obtenez un Élixir d'avidité.<br>Quand vous atteignez le niveau 6, vous obtenez un Élixir de force.<br>Quand vous atteignez le niveau 9, vous obtenez un Élixir de compétence. ","longDesc":"Quand vous atteignez le niveau 3, vous obtenez un Élixir d'avidité.<br>Quand vous atteignez le niveau 6, vous obtenez un Élixir de force.<br>Quand vous atteignez le niveau 9, vous obtenez un Élixir de compétence. "},"8352":{"name":"Philtre de chronodistorsion","icon":"perk-images/Styles/Inspiration/TimeWarpTonic/TimeWarpTonic.png","style":8300,"slot":2,"shortDesc":"Les potions vous rendent immédiatement une partie des PV prévus.","longDesc":"Consommer une potion vous rend immédiatement 40% des PV prévus."},"8345":{"name":"Livraison de biscuits","icon":"perk-images/Styles/Inspiration/BiscuitDelivery/BiscuitDelivery.png","style":8300,"slot":2,"shortDesc":"Vous gagnez un biscuit gratuit toutes les 2 min, jusqu'à 6 min de jeu. Consommer ou vendre un biscuit augmente définitivement vos PV max et vous rend des PV.","longDesc":"Livraison de biscuits : vous gagnez 1 Biscuit de longévité toutes les 2 minutes, jusqu'à 6 minutes de jeu.<br><br>Les biscuits vous rendent 20 + 2% de vos PV max. Ces soins augmentés de 100% en fonction de vos PV manquants. Consommer ou vendre un biscuit augmente définitivement vos PV max de 30. "},"8347":{"name":"Savoir cosmique","icon":"perk-images/Styles/Inspiration/CosmicInsight/CosmicInsight.png","style":8300,"slot":3,"shortDesc":"+<attention>18</attention> accélération de sort d'invocateur<br>+<attention>10</attention> accélération d'objet","longDesc":"+<attention>18</attention> accélération de sort d'invocateur<br>+<attention>10</attention> accélération d'objet"},"8410":{"name":"Vitesse d'approche","icon":"perk-images/Styles/Resolve/ApproachVelocity/ApproachVelocity.png","style":8300,"slot":3,"shortDesc":"Votre <lol-uikit-tooltipped-keyword key='LinkTooltip_Description_MS'>vitesse de déplacement</lol-uikit-tooltipped-keyword> augmente vers les champions ennemis proches dont <lol-uikit-tooltipped-keyword key='LinkTooltip_Description_ImpairMov'>les déplacements sont restreints</lol-uikit-tooltipped-keyword>, et elle augmente davantage vers les champions ennemis dont vous avez restreint les déplacements.","longDesc":"Vous gagnez <speed>+7.5% de vitesse de déplacement</speed> vers les champions ennemis proches dont les déplacements sont restreints. Ce bonus est augmenté à <speed>15%</speed> vers les champions ennemis dont vous avez restreint les déplacements. <br><br>Portée d'activation pour les contrôles de foule alliés : 1000."},"8316":{"name":"Polyvalence","icon":"perk-images/Styles/Inspiration/JackOfAllTrades/JackofAllTrades2.png","style":8300,"slot":3,"shortDesc":"Vous gagnez un effet Polyvalence pour chaque stat différente octroyée par vos objets. Chaque effet vous octroie <speed>+1 accélération de compétence</speed>.<br><br>Vous gagnez de la <lol-uikit-tooltipped-keyword key='LinkTooltip_Description_Adaptive'>force adaptative</lol-uikit-tooltipped-keyword> à 5 et 10 effets cumulés.","longDesc":"Vous gagnez un effet Polyvalence pour chaque stat différente octroyée par vos objets. Chaque effet cumulé vous octroie <speed>1 accélération de compétence</speed>.<br><br>Vous gagnez 8 et 20 de <lol-uikit-tooltipped-keyword key='LinkTooltip_Description_Adaptive'>force adaptative</lol-uikit-tooltipped-keyword> bonus en cumulant respectivement 5 et 10 effets."},"8005":{"name":"Attaque soutenue","icon":"perk-images/Styles/Precision/PressTheAttack/PressTheAttack.png","style":8000,"slot":0,"shortDesc":"Toucher un champion ennemi 3 fois de suite lui inflige des dégâts bonus et augmente vos dégâts jusqu'à ce que vous quittiez le combat contre des champions.","longDesc":"Toucher un champion ennemi avec 3 attaques de base consécutives inflige 40 - 160 pts de <lol-uikit-tooltipped-keyword key='LinkTooltip_Description_AdaptiveDmg'><font color='#48C4B7'>dégâts adaptatifs</font></lol-uikit-tooltipped-keyword> bonus (selon le niveau) et augmente les dégâts que vous infligez de 8% jusqu'à ce que vous quittiez le combat contre des champions."},"8008":{"name":"Tempo mortel","icon":"perk-images/Styles/Precision/LethalTempo/LethalTempoTemp.png","style":8000,"slot":0,"shortDesc":"Attaquer un champion ennemi vous octroie de la vitesse d'attaque (6 effets cumulés max.). Au maximum d'effets cumulés, vous infligez également des <lol-uikit-tooltipped-keyword key='LinkTooltip_Description_AdaptiveDmg'><font color='#48C4B7'>dégâts adaptatifs bonus</font></lol-uikit-tooltipped-keyword> à l'attaque.","longDesc":"Attaquer un champion ennemi vous octroie +[6% pour les champions en mêlée || 4% pour les champions à distance] vitesse d'attaque pendant 6 sec (6 effets cumulés max.). Au maximum d'effets cumulés, vous infligez également [9 - 30 pour les champions en mêlée || 6 - 24 pour les champions à distance] <lol-uikit-tooltipped-keyword key='LinkTooltip_Description_AdaptiveDmg'>pts de dégâts adaptatifs bonus à l'attaque. Ces dégâts augmentent de 1% tous les 1% de vitesse d'attaque bonus</lol-uikit-tooltipped-keyword>."},"8021":{"name":"Jeu de jambes","icon":"perk-images/Styles/Precision/FleetFootwork/FleetFootwork.png","style":8000,"slot":0,"shortDesc":"Attaquer et se déplacer génère des effets Énergie. À 100 effets cumulés, votre prochaine attaque vous soigne et augmente votre <lol-uikit-tooltipped-keyword key='LinkTooltip_Description_MS'>vitesse de déplacement</lol-uikit-tooltipped-keyword>.","longDesc":"Attaquer et se déplacer génère des effets Énergie. À 100 effets cumulés, votre prochaine attaque est énergisée.<br><br>Les attaques énergisées vous rendent 15 - 160 (+0.1 dégâts d'attaque bonus, +0.05 puissance) PV et vous octroient <speed>+20% de vitesse de déplacement</speed> pendant 1 sec.<br><br>Pour les champions à distance, l'efficacité des soins est de 60% et l'efficacité de la vitesse de déplacement est de 75%. Contre les sbires, l'efficacité de tous les soins est de 15%."},"8010":{"name":"Conquérant","icon":"perk-images/Styles/Precision/Conqueror/Conqueror.png","style":8000,"slot":0,"shortDesc":"Attaquer des champions ennemis vous fait gagner de la force adaptative cumulable. À 12 effets cumulés, vous récupérez des PV équivalents à une partie des dégâts que vous infligez aux champions.","longDesc":"Les attaques de base et les compétences qui blessent un champion ennemi génèrent 2 effets Conquérant pendant 5 sec, octroyant +1.8 - 4 <lol-uikit-tooltipped-keyword key='LinkTooltip_Description_Adaptive'><font color='#48C4B7'>force adaptative</font></lol-uikit-tooltipped-keyword> par effet cumulé. Cumulable 12 fois. Les champions à distance ne gagnent qu'un effet par attaque de base.<br><br>Au maximum d'effets cumulés, vous récupérez des PV équivalents à 8% des dégâts que vous infligez aux champions (5% pour les champions à distance)."},"9101":{"name":"Absorption vitale","icon":"perk-images/Styles/Precision/AbsorbLife/AbsorbLife.png","style":8000,"slot":1,"shortDesc":"Tuer une cible vous rend des PV.","longDesc":"Tuer une cible vous rend @HealAmount@ PV."},"9111":{"name":"Triomphe","icon":"perk-images/Styles/Precision/Triumph.png","style":8000,"slot":1,"shortDesc":"Participer à l'élimination d'un champion vous rend 5% de vos PV manquants et vous rapporte 20 PO supplémentaires. ","longDesc":"Participer à l'élimination d'un champion vous rend 5% de vos PV manquants, 2.5% de vos PV max et vous rapporte 20 PO supplémentaires. <br><br><hr><br><i>« La proie la plus dangereuse rapporte la gloire la plus grande. » <br>—Arénaire noxien</i>"},"8009":{"name":"Présence d'esprit","icon":"perk-images/Styles/Precision/PresenceOfMind/PresenceOfMind.png","style":8000,"slot":1,"shortDesc":"Blesser un champion ennemi vous rend un peu de mana ou d'énergie. Participer à l'élimination d'un champion vous rend du mana ou de l'énergie.","longDesc":"Infliger des dégâts à un champion ennemi vous rend 6 - 50 (80% pour les champions à distance) pts de mana ou 6 pts d'énergie.<br><br>Participer à l'élimination d'un champion vous rend 15% de votre mana max ou de votre énergie max. <br><br>Délai de récupération pour la récupération via les dégâts : 8 sec."},"9104":{"name":"Légende : alacrité","icon":"perk-images/Styles/Precision/LegendAlacrity/LegendAlacrity.png","style":8000,"slot":2,"shortDesc":"Participer à <lol-uikit-tooltipped-keyword key='LinkTooltip_Description_Takedown'>l'élimination</lol-uikit-tooltipped-keyword> d'ennemis augmente définitivement votre <b>vitesse d'attaque</b>. ","longDesc":"Vous gagnez 3% de vitesse d'attaque plus 1.5% par effet <i>Légende</i> cumulé (<statGood>max : 10</statGood>).<br><br>Vous progressez vers l'obtention d'un effet <i>Légende</i> chaque fois que vous participez à l'élimination d'un champion ou d'un monstre épique, et chaque fois que vous tuez un grand monstre ou un sbire."},"9105":{"name":"Légende : accélération","icon":"perk-images/Styles/Precision/LegendHaste/LegendHaste.png","style":8000,"slot":2,"shortDesc":"Participer à l'<lol-uikit-tooltipped-keyword key='LinkTooltip_Description_Takedown'>élimination</lol-uikit-tooltipped-keyword> d'ennemis augmente définitivement votre <b>accélération de compétence</b> de base. ","longDesc":"Vous gagnez +1.5 accélération de compétence de base par effet <i>Légende</i> cumulé (<statGood>max : 10</statGood>).<br><br>Vous progressez vers l'obtention d'un effet <i>Légende</i> chaque fois que vous participez à l'élimination d'un champion ou d'un monstre épique, et chaque fois que vous tuez un grand monstre ou un sbire."},"9103":{"name":"Légende : sangsue","icon":"perk-images/Styles/Precision/LegendBloodline/LegendBloodline.png","style":8000,"slot":2,"shortDesc":"Participer à <lol-uikit-tooltipped-keyword key='LinkTooltip_Description_Takedown'>l'élimination</lol-uikit-tooltipped-keyword> d'ennemis augmente définitivement votre <b>vol de vie</b>, jusqu'à un maximum. Une fois ce maximum atteint, participer à une élimination augmente vos PV max. Cette rune est plus faible en début de partie et plus puissante en fin de partie que les autres runes Légende.","longDesc":"Vous gagnez <scaleAD>0.45% de vol de vie</scaleAD> par effet <i>Légende</i> cumulé (<statGood>max 15</statGood>). Au maximum d'effets <i>Légende</i> cumulés, vous gagnez <scaleHealth>+85 PV max</scaleHealth>.<br><br>Vous progressez vers l'obtention d'un effet <i>Légende</i> chaque fois que vous participez à l'élimination d'un champion ou d'un monstre épique, et chaque fois que vous tuez un grand monstre ou un sbire."},"8014":{"name":"Coup de grâce","icon":"perk-images/Styles/Precision/CoupDeGrace/CoupDeGrace.png","style":8000,"slot":3,"shortDesc":"Vous infligez plus de dégâts aux champions à qui il reste peu de PV.","longDesc":"Vous infligez 8% de dégâts supplémentaires aux champions qui ont moins de 40% de leurs PV."},"8017":{"name":"Abattage","icon":"perk-images/Styles/Precision/CutDown/CutDown.png","style":8000,"slot":3,"shortDesc":"Vous infligez plus de dégâts aux champions qui ont beaucoup de PV.","longDesc":"Vous infligez 8% de dégâts supplémentaires aux champions qui ont plus de 60% de leurs PV."},"8299":{"name":"Baroud d'honneur","icon":"perk-images/Styles/Sorcery/LastStand/LastStand.png","style":8000,"slot":3,"shortDesc":"Vous infligez plus de dégâts aux champions quand il vous reste peu de PV.","longDesc":"Vous infligez 5% - 11% de dégâts supplémentaires aux champions quand vous avez moins de 60% de vos PV. Les dégâts max sont atteints à 30% de vos PV."},"8437":{"name":"Poigne de l'immortel","icon":"perk-images/Styles/Resolve/GraspOfTheUndying/GraspOfTheUndying.png","style":8400,"slot":0,"shortDesc":"Toutes les 4 sec, votre prochaine attaque contre un champion inflige des dégâts magiques supplémentaires, vous soigne et augmente définitivement vos PV.","longDesc":"Toutes les 4 sec en combat, votre prochaine attaque de base contre un champion :<li>Inflige des dégâts magiques bonus équivalents à 3.5% de vos PV max.<li>Vous rend 1.3% de vos PV max.<li>Augmente définitivement vos PV de 5.<br><rules><i>Champions à distance :</i> les dégâts, les soins et le gain définitif de PV sont efficaces à 40%.</rules>"},"8439":{"name":"Après-coup","icon":"perk-images/Styles/Resolve/VeteranAftershock/VeteranAftershock.png","style":8400,"slot":0,"shortDesc":"Après avoir <lol-uikit-tooltipped-keyword key='LinkTooltip_Description_Immobilize'>immobilisé</lol-uikit-tooltipped-keyword> un champion ennemi, vous augmentez vos défenses, puis vous infligez des dégâts magiques autour de vous.","longDesc":"Après avoir immobilisé un champion ennemi, votre armure et votre résistance magique augmentent de 45 + 75% de vos résistances bonus pendant 2.5 sec. Une explosion se produit ensuite, infligeant des dégâts magiques aux ennemis proches.<br><br>Dégâts : 25 - 120 (+8% de vos PV bonus).<br>Délai de récupération : 20 sec.<br><br>Les bonus de résistance d'Après-coup sont limités à : 80-150 (selon le niveau).<br>"},"8465":{"name":"Gardien","icon":"perk-images/Styles/Resolve/Guardian/Guardian.png","style":8400,"slot":0,"shortDesc":"Vous protégez les alliés sur lesquels vous lancez des compétences et ceux qui sont très proches. Si un allié protégé ou vous-même devriez subir des dégâts (selon le niveau), vous recevez tous les deux un bouclier.","longDesc":"Vous <i>protégez</i> les alliés à moins de 350 unités de vous et les alliés que vous ciblez avec vos compétences pendant 2.5 sec. Pendant cette <i>protection</i>, si cet allié ou vous-même subissez plus que des dégâts mineurs, vous recevez tous les deux un bouclier pendant 1.5 sec.<br><br>Délai de récupération : <scaleLevel>75 - 40</scaleLevel> sec.<br>Bouclier : <scaleLevel>40 - 150</scaleLevel> + <scaleAP>20%</scaleAP> de votre puissance + <scalehealth>6%</scalehealth> de vos PV supplémentaires.<br>Seuil de déclenchement : <scaleLevel>50 - 165</scaleLevel> pts de dégâts après mitigation."},"8446":{"name":"Démolition","icon":"perk-images/Styles/Resolve/Demolish/Demolish.png","style":8400,"slot":1,"shortDesc":"Votre troisième attaque contre des tourelles inflige des dégâts bonus.","longDesc":"Votre troisième attaque contre les tourelles inflige [85 (+28% des PV max) en mêlée || 50 (+20% des PV max) à distance] pts de dégâts physiques bonus.<br><br>Délai de récupération : 30 sec."},"8463":{"name":"Fontaine de vie","icon":"perk-images/Styles/Resolve/FontOfLife/FontOfLife.png","style":8400,"slot":1,"shortDesc":"<lol-uikit-tooltipped-keyword key='LinkTooltip_Description_ImpairMov'>Restreindre</lol-uikit-tooltipped-keyword> les déplacements d'un champion ennemi soigne les champions alliés proches. ","longDesc":"Restreindre les déplacements d'un champion ennemi rend <healing>@BaseHeal@ PV</healing> au champion allié proche qui a le moins de PV et à vous-même.<br><br>70% d'efficacité pour les utilisateurs à distance.<br><br>Délai de récupération : 20 sec."},"8401":{"name":"Coup de bouclier","icon":"perk-images/Styles/Resolve/MirrorShell/MirrorShell.png","style":8400,"slot":1,"shortDesc":"Quand vous recevez un bouclier, votre prochaine attaque de base contre un champion inflige des dégâts <lol-uikit-tooltipped-keyword key='LinkTooltip_Description_Adaptive'><font color='#48C4B7'>adaptatifs</font></lol-uikit-tooltipped-keyword> supplémentaires.","longDesc":"Quand vous recevez un nouveau bouclier, votre prochaine attaque de base contre un champion inflige <scaleLevel>5 - 30</scaleLevel> <scaleHealth>(+2.5% de vos PV bonus)</scaleHealth> <scaleMana>(+15.0% des PV du nouveau bouclier)</scaleMana> pts de dégâts <lol-uikit-tooltipped-keyword key='LinkTooltip_Description_Adaptive'><font color='#48C4B7'>adaptatifs</font></lol-uikit-tooltipped-keyword> bonus.<br><br>Après l'expiration du bouclier, vous avez 2 sec pour utiliser cet effet."},"8429":{"name":"Conditionnement","icon":"perk-images/Styles/Resolve/Conditioning/Conditioning.png","style":8400,"slot":2,"shortDesc":"Après 12 min de jeu, vous gagnez +8 armure et +8 résistance magique et vous augmentez votre armure et votre résistance magique de 3%.","longDesc":"Après 12 min de jeu, vous gagnez +8 armure et +8 résistance magique et vous augmentez votre armure et votre résistance magique de 3%."},"8444":{"name":"Second souffle","icon":"perk-images/Styles/Resolve/SecondWind/SecondWind.png","style":8400,"slot":2,"shortDesc":"Après avoir subi des dégâts d'un champion ennemi, vous récupérez une partie de vos PV manquants sur la durée. ","longDesc":"Après avoir subi des dégâts d'un champion ennemi, vous récupérez 4% de vos PV manquants en 10 sec."},"8473":{"name":"Plaque d'os","icon":"perk-images/Styles/Resolve/BonePlating/BonePlating.png","style":8400,"slot":2,"shortDesc":"Après avoir subi des dégâts d'un champion ennemi, ses 3 prochaines compétences ou attaques vous infligent 30-60 pts de dégâts en moins (selon le niveau).<br><br>Durée : 1.5 sec.<br>Délai de récupération : 55 sec.","longDesc":"Après avoir subi des dégâts d'un champion ennemi, ses 3 prochaines compétences ou attaques vous infligent 30-60 pts de dégâts en moins (selon le niveau).<br><br>Durée : 1.5 sec.<br>Délai de récupération : 55 sec."},"8451":{"name":"Surcroissance","icon":"perk-images/Styles/Resolve/Overgrowth/Overgrowth.png","style":8400,"slot":3,"shortDesc":"Vos PV max augmentent définitivement quand des sbires et des monstres meurent près de vous.","longDesc":"Vous absorbez l'essence vitale des monstres et sbires ennemis proches. Tous les 8 monstres ou sbires ennemis qui meurent près de vous, vos PV max augmentent définitivement de 3.<br><br>Après avoir absorbé l'essence de 120 monstres ou sbires ennemis, vous gagnez 3.5% de PV max supplémentaires."},"8453":{"name":"Revitalisation","icon":"perk-images/Styles/Resolve/Revitalize/Revitalize.png","style":8400,"slot":3,"shortDesc":"Vous gagnez +5% d'efficacité des soins et boucliers.<br><br>Les soins et les boucliers que vous lancez ou recevez sont 10% plus puissants sur les cibles qui ont moins de 40% de leurs PV.","longDesc":"Vous gagnez +5% d'efficacité des soins et boucliers.<br><br>Les soins et les boucliers que vous lancez ou recevez sont 10% plus puissants sur les cibles qui ont moins de 40% de leurs PV."},"8242":{"name":"Inébranlable","icon":"perk-images/Styles/Sorcery/Unflinching/Unflinching.png","style":8400,"slot":3,"shortDesc":"Vous gagnez de l'armure et de la résistance magique quand vous êtes victime d'un contrôle de foule.","longDesc":"Vous obtenez +10 armure et résistance magique quand vous êtes victime d'un contrôle de foule et ensuite pendant 2 sec."},"8214":{"name":"Invocation d'Aery","icon":"perk-images/Styles/Sorcery/SummonAery/SummonAery.png","style":8200,"slot":0,"shortDesc":"Vos attaques et vos compétences envoient Aery vers une cible, blessant les ennemis ou protégeant les alliés.","longDesc":"Blesser un champion ennemi avec une attaque de base ou une compétence envoie Aery vers lui, lui infligeant 10 - 50 selon le niveau (+<scaleAP>0.05 puissance</scaleAP>) (+<scaleAD>0.1 dégâts d'attaque supplémentaires</scaleAD>).<br><br>Renforcer ou protéger un allié avec une compétence envoie Aery vers lui, lui octroyant un bouclier absorbant 20 - 100 selon le niveau (+<scaleAP>0.05 puissance</scaleAP>) (+<scaleAD>0.1 dégâts d'attaque bonus</scaleAD>).<br><br>Aery ne peut plus être envoyée tant qu'elle n'est pas revenue auprès de vous."},"8229":{"name":"Comète arcanique","icon":"perk-images/Styles/Sorcery/ArcaneComet/ArcaneComet.png","style":8200,"slot":0,"shortDesc":"Blesser un champion avec une compétence fait tomber une comète destructrice sur sa position.","longDesc":"Blesser un champion avec une compétence fait tomber une comète sur sa position, infligeant des dégâts augmentés selon la distance.<br><br><lol-uikit-tooltipped-keyword key='LinkTooltip_Description_AdaptiveDmg'><font color='#48C4B7'>Dégâts adaptatifs</font></lol-uikit-tooltipped-keyword> : 15 - 100 selon le niveau (<scaleAP>+0.05 puissance</scaleAP> et <scaleAD>+0.1 dégâts d'attaque bonus</scaleAD>)<br>Délai de récupération : 20 - 8 sec<br><rules><br>L'amplification des dégâts augmente jusqu'à 100% à 750 de portée.<br></rules>"},"8230":{"name":"Assaut du maraudeur","icon":"perk-images/Styles/Sorcery/PhaseRush/StormraidersSurgeRuneIcon2.png","style":8200,"slot":0,"shortDesc":"Infliger 25% des PV max d'un champion vous octroie une brève augmentation de <lol-uikit-tooltipped-keyword key='LinkTooltip_Description_MS'>vitesse de déplacement</lol-uikit-tooltipped-keyword> et de résistance aux ralentissements. ","longDesc":"Infliger 25% des PV max d'un champion en moins de 3 sec octroie <speed>48% de vitesse de déplacement</speed> et <status>50% de résistance aux ralentissements</status> pendant 4 sec. La vitesse de déplacement a 75% d'efficacité pour les champions à distance.<br>Délai de récupération : 20 sec - 10 sec."},"8992":{"name":"Toucher de feu mortel","icon":"perk-images/Styles/Sorcery/DeathfireTouch/DEATHFIRE_TOUCH_KEYSTONE.png","style":8200,"slot":0,"shortDesc":"Blesser un champion avec une compétence le brûle sur la durée.","longDesc":"Blesser un champion avec une compétence le brûle, en fonction du niveau, de 3 - 12 (+<scaleAP>2.5% de la puissance</scaleAP>) (+<scaleAD>7% des dégâts d'attaque bonus</scaleAD>) pts de dégâts magiques par seconde. Après avoir brûlé pendant 3 sec, les dégâts de la brûlure augmentent de 75% tant que la cible reste en feu.<br><rules><br>Durée :<br>Cible unique : 4 sec.<br>Dégâts de zone : 2 sec.<br>Dégâts sur la durée : 1 sec.<br></rules>"},"8224":{"name":"Arcaniste axiomatique","icon":"perk-images/Styles/Sorcery/NullifyingOrb/Axiom_Arcanist.png","style":8200,"slot":1,"shortDesc":"Les dégâts, les soins et les boucliers de votre compétence ultime sont augmentés. Participer à l'élimination d'un champion ennemi réduit le délai de récupération actuel de votre compétence ultime.","longDesc":"Les dégâts, les soins et les boucliers de votre compétence ultime sont augmentés de 12%. <br>(Les dégâts de zone sont augmentés de 8% à la place.)<br><br>Participer à l'élimination d'un champion ennemi réduit le délai de récupération actuel de votre compétence ultime de 7%."},"8226":{"name":"Ruban de mana","icon":"perk-images/Styles/Sorcery/ManaflowBand/ManaflowBand.png","style":8200,"slot":1,"shortDesc":"Frapper un champion ennemi avec une compétence augmente définitivement votre mana max de 25 (bonus max : 250).<br><br>À 250 pts de mana bonus, vous récupérez 1% de votre mana manquant toutes les 5 sec.","longDesc":"Frapper un champion ennemi avec une compétence augmente définitivement votre mana max de 25 (bonus max : 250).<br><br>À 250 pts de mana bonus, vous récupérez 1% de votre mana manquant toutes les 5 sec.<br><br>Délai de récupération : 15 sec."},"8275":{"name":"Manteau nuageux","icon":"perk-images/Styles/Sorcery/NimbusCloak/6361.png","style":8200,"slot":1,"shortDesc":"Après avoir lancé un sort d'invocateur, vous gagnez un bref bonus en <speed>vitesse de déplacement</speed> qui vous permet de traverser les unités.","longDesc":"Après avoir lancé un sort d'invocateur, vous gagnez un bonus en <speed>vitesse de déplacement</speed> qui dure 2 sec et qui vous permet de traverser les unités.<br><br>Bonus : <speed>+15% - +45% de vitesse de déplacement</speed>, selon le délai de récupération du sort d'invocateur (plus le délai de récupération est élevé, plus le bonus est important). "},"8210":{"name":"Transcendance","icon":"perk-images/Styles/Sorcery/Transcendence/Transcendence.png","style":8200,"slot":2,"shortDesc":"Vous gagnez des bonus en atteignant les niveaux suivants :<br>Niveau 5 : +5 <lol-uikit-tooltipped-keyword key='LinkTooltip_Description_CDR'>accélération de compétence</lol-uikit-tooltipped-keyword> <br>Niveau 8 : +5 <lol-uikit-tooltipped-keyword key='LinkTooltip_Description_CDR'>accélération de compétence</lol-uikit-tooltipped-keyword> <br>Niveau 11 : participer à l'élimination d'un champion réduit de 20% le délai de récupération restant des compétences de base.","longDesc":"Vous gagnez des bonus en atteignant les niveaux suivants :<br>Niveau 5 : +5 <lol-uikit-tooltipped-keyword key='LinkTooltip_Description_CDR'>accélération de compétence</lol-uikit-tooltipped-keyword> <br>Niveau 8 : +5 <lol-uikit-tooltipped-keyword key='LinkTooltip_Description_CDR'>accélération de compétence</lol-uikit-tooltipped-keyword> <br>Niveau 11 : participer à l'élimination d'un champion réduit de 20% le délai de récupération restant des compétences de base."},"8234":{"name":"Célérité","icon":"perk-images/Styles/Sorcery/Celerity/CelerityTemp.png","style":8200,"slot":2,"shortDesc":"Tous les bonus en <speed>vitesse de déplacement</speed> sont 7% plus efficaces sur vous et votre <speed>vitesse de déplacement</speed> est augmentée de 1%.","longDesc":"Tous les bonus en vitesse de déplacement sont 7% plus efficaces sur vous et votre <speed>vitesse de déplacement</speed> est augmentée de 1%."},"8233":{"name":"Concentration absolue","icon":"perk-images/Styles/Sorcery/AbsoluteFocus/AbsoluteFocus.png","style":8200,"slot":2,"shortDesc":"Quand vous avez plus de 70% de vos PV, vous gagnez des <lol-uikit-tooltipped-keyword key='LinkTooltip_Description_AdaptiveDmg'>dégâts adaptatifs</lol-uikit-tooltipped-keyword>.","longDesc":"Quand vous avez plus de 70% de vos PV, vous gagnez un bonus <lol-uikit-tooltipped-keyword key='LinkTooltip_Description_Adaptive'><font color='#48C4B7'>adaptatif</font></lol-uikit-tooltipped-keyword> de jusqu'à 18 dégâts d'attaque ou 30 puissance (selon le niveau). <br><br>Octroie +1.8 dégâts d'attaque ou +3 puissance au niveau 1. "},"8237":{"name":"Brûlure","icon":"perk-images/Styles/Sorcery/Scorch/Scorch.png","style":8200,"slot":3,"shortDesc":"Toutes les 10 sec, votre prochaine compétence qui inflige des dégâts met le feu aux champions.","longDesc":"Votre prochaine compétence blessante met le feu aux champions, infligeant 20 - 40 pts de dégâts magiques supplémentaires (selon le niveau) après 1 sec.<br><br>Délai de récupération : 10 sec."},"8232":{"name":"Marche sur l'eau","icon":"perk-images/Styles/Sorcery/Waterwalking/Waterwalking.png","style":8200,"slot":3,"shortDesc":"Dans la rivière, vous gagnez de la <lol-uikit-tooltipped-keyword key='LinkTooltip_Description_MS'>vitesse de déplacement</lol-uikit-tooltipped-keyword> et de la puissance ou des dégâts d'attaque (<lol-uikit-tooltipped-keyword key='LinkTooltip_Description_Adaptive'>bonus adaptatif</lol-uikit-tooltipped-keyword>).","longDesc":"Dans la rivière, vous gagnez <speed>+10 vitesse de déplacement</speed> et <lol-uikit-tooltipped-keyword key='LinkTooltip_Description_Adaptive'><font color='#48C4B7'>+13 - +30 force adaptative</font></lol-uikit-tooltipped-keyword> (selon le niveau).<br><br><i>Puissiez-vous être aussi vif qu'une rivière et aussi agile qu'un carapateur effrayé.</i>"},"8236":{"name":"Tempête menaçante","icon":"perk-images/Styles/Sorcery/GatheringStorm/GatheringStorm.png","style":8200,"slot":3,"shortDesc":"Vous gagnez de plus en plus de dégâts d'attaque ou de puissance (<lol-uikit-tooltipped-keyword key='LinkTooltip_Description_Adaptive'>bonus adaptatif</lol-uikit-tooltipped-keyword>) au fil de la partie.","longDesc":"Vous gagnez de la puissance ou des dégâts d'attaque toutes les 10 min (<lol-uikit-tooltipped-keyword key='LinkTooltip_Description_Adaptive'><font color='#48C4B7'>bonus adaptatif</font></lol-uikit-tooltipped-keyword>).<br><br><i>10 min</i> : +8 puissance ou +5 dégâts d'attaque <br><i>20 min</i> : +24 puissance ou +14 dégâts d'attaque<br><i>30 min</i> : +48 puissance ou +29 dégâts d'attaque<br><i>40 min</i> : +80 puissance ou +48 dégâts d'attaque<br><i>50 min</i> : +120 puissance ou +72 dégâts d'attaque<br><i>60 min</i> : +168 puissance ou +101 dégâts d'attaque,<br>etc."}};
